import { after } from 'next/server';
import { headers } from 'next/headers';

/**
 * Simulates a logging call to an external analytics service.
 * This function deliberately simulates a slow operation to demonstrate non-blocking behavior.
 */
async function logPageView(data: { userAgent: string; timestamp: string }) {
  // Simulate network latency (e.g., 2 seconds)
  await new Promise((resolve) => setTimeout(resolve, 2000));

  console.log('[Analytics] Page view logged successfully:', data);
}

export default async function Home() {
  // Read request data before `after` because Dynamic APIs like `headers()`
  // cannot be called inside `after` when used in a Server Component.
  const headersList = await headers();
  const userAgent = headersList.get('user-agent') || 'unknown';
  const timestamp = new Date().toISOString();

  // Schedule the logging task to run after the response is sent
  after(async () => {
    await logPageView({ userAgent, timestamp });
  });

  return (
    <main style={{ 
      fontFamily: 'system-ui, sans-serif', 
      padding: '2rem', 
      maxWidth: '600px', 
      margin: '0 auto' 
    }}>
      <h1 style={{ fontSize: '2.5rem', marginBottom: '1rem' }}>Welcome!</h1>
      <p style={{ fontSize: '1.2rem', lineHeight: '1.6', color: '#444' }}>
        Thank you for visiting our site.
      </p>
      <p style={{ fontSize: '1rem', color: '#666', marginTop: '2rem', padding: '1rem', background: '#f5f5f5', borderRadius: '8px' }}>
        <strong>Note:</strong> Your page view is being logged to our analytics service in the background, 
        without delaying the loading of this page. Check the server console to see the log appear after a delay.
      </p>
    </main>
  );
}

